logic [7:0] RxDataEsc;
logic RxLPDTEsc, RxValidEsc;
logic TxRequestHSc, TxStopStateC;
logic TxUlpsClk, TxUlpsExitClk, TxUlpsActiveClkNot;
logic TurnRequest, turnaround_timeout; 
logic TxStopState_1P, TxStopState_2P;

